import {test} from 'node:test';
import assert from 'node:assert/strict';
import {fixture} from './helpers.js';
import {totals} from '../src/cart.js';
test('cart create, merge, update, remove and current totals',async t=>{
 const {request}=await fixture(t);const created=await request('/api/carts','POST');assert.equal(created.status,201);
 const id=created.body.id;assert.deepEqual(created.body.items,[]);assert.equal(created.body.totalCents,0);
 let added=await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity:2});assert.equal(added.status,200);assert.equal(added.body.totalCents,2700);
 added=await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity:1});assert.equal(added.body.items.length,1);assert.equal(added.body.items[0].quantity,3);
 assert.equal((await request('/api/carts/'+id+'/items/mug-classic','PATCH',{quantity:1})).body.subtotalCents,1250);
 assert.equal((await request('/api/carts/'+id+'/items/mug-classic','PATCH',{quantity:0})).body.items.length,0);
 await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity:1});
 assert.equal((await request('/api/carts/'+id+'/items/mug-classic','DELETE')).body.items.length,0);
 assert.equal((await request('/api/carts/'+id+'/items/mug-classic','DELETE')).status,404);
 assert.equal((await request('/api/carts/missing')).status,404);
});
test('cart validation and stock do not reserve stock',async t=>{
 const {request}=await fixture(t);const id=(await request('/api/carts','POST')).body.id;
 for(const quantity of [0,-1,100,1.5,'2',null])assert.equal((await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity})).status,400);
 assert.equal((await request('/api/carts/'+id+'/items','POST',{quantity:1})).status,400);
 assert.equal((await request('/api/carts/'+id+'/items','POST',{productId:'unknown',quantity:1})).status,404);
 assert.equal((await request('/api/carts/'+id+'/items','POST',{productId:'notebook-blue',quantity:1})).body.error.code,'OUT_OF_STOCK');
 await request('/api/carts/'+id+'/items','POST',{productId:'tote-canvas',quantity:1});
 assert.equal((await request('/api/carts/'+id+'/items','POST',{productId:'tote-canvas',quantity:1})).status,409);
 assert.equal((await request('/api/carts/'+id+'/items/tote-canvas','PATCH',{quantity:2})).status,409);
 assert.equal((await request('/api/products/tote-canvas')).body.stock,1);
 assert.equal((await request('/api/carts/'+id+'/items/tote-canvas','PATCH',{quantity:-1})).status,400);
});
test('tax rounds half up in integer cents',()=>{
 assert.deepEqual(totals(7),{subtotalCents:7,discountCents:0,taxCents:1,totalCents:8});
 assert.equal(totals(6).taxCents,0);assert.equal(totals(100,25).totalCents,81);
});

